// Get the computed styles and fonts used on the page
const allElements = document.querySelectorAll('*');
const fonts = new Set();
const colors = new Set();
const bgColors = new Set();
const borderRadii = new Set();

allElements.forEach(el => {
  const style = getComputedStyle(el);
  fonts.add(style.fontFamily.split(',')[0].trim());
  if (style.color !== 'rgba(0, 0, 0, 0)') colors.add(style.color);
  if (style.backgroundColor !== 'rgba(0, 0, 0, 0)') bgColors.add(style.backgroundColor);
  if (style.borderRadius !== '0px') borderRadii.add(style.borderRadius);
});

JSON.stringify({
  fonts: [...fonts].slice(0, 15),
  colors: [...colors].slice(0, 15),
  bgColors: [...bgColors].slice(0, 15),
  borderRadii: [...borderRadii].slice(0, 10)
}, null, 2);

