from html.parser import HTMLParser
class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        void_tags = {'br','hr','img','input','meta','link','area','base','col','embed','source','track','wbr'}
        if tag not in void_tags:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            while self.stack and self.stack[-1] != tag:
                self.errors.append(f'Unclosed: {self.stack.pop()}')
            if self.stack:
                self.stack.pop()

with open('/sessions/stoic-relaxed-carson/mnt/outputs/design-compare.html') as f:
    html = f.read()

c = Checker()
c.feed(html)
print(f'File size: {len(html)} bytes')
print(f'Lines: {html.count(chr(10))+1}')
print(f'Sections found: {html.count(\"section-title\")}')
print(f'Option cards found: {html.count(\"class=\\\"oc\\\"\")}')
print(f'Remaining stack: {c.stack[-5:] if c.stack else \"clean\"}')
print(f'Errors: {c.errors[:5] if c.errors else \"none\"}}')
