// Extract detailed computed styles from all key elements on the landing page
const results = {};

// Body
const body = document.body;
const bodyCS = getComputedStyle(body);
results.body = { bg: bodyCS.backgroundColor, font: bodyCS.fontFamily, color: bodyCS.color };

// Find heading "Built for IB recruiting."
const allH = document.querySelectorAll('h1, h2, h3, [class*="heading"], [class*="title"]');
allH.forEach((h, i) => {
  const cs = getComputedStyle(h);
  const text = h.textContent?.trim().substring(0, 50);
  if (text && text.length > 3) {
    results[`heading_${i}`] = { text, font: cs.fontFamily, size: cs.fontSize, weight: cs.fontWeight, color: cs.color, letterSpacing: cs.letterSpacing };
  }
});

// Find "Unfiltered." italic text
const italics = document.querySelectorAll('em, i, [class*="italic"], [class*="accent"]');
italics.forEach((el, i) => {
  const cs = getComputedStyle(el);
  results[`italic_${i}`] = { text: el.textContent?.trim().substring(0, 30), font: cs.fontFamily, size: cs.fontSize, weight: cs.fontWeight, style: cs.fontStyle, color: cs.color };
});

// Find the access card
const cards = document.querySelectorAll('[class*="card"], [class*="bg-"]');
const cardEl = Array.from(cards).find(c => c.textContent.includes('access code'));
if (cardEl) {
  const cs = getComputedStyle(cardEl);
  results.accessCard = { bg: cs.backgroundColor, borderRadius: cs.borderRadius, border: cs.border, padding: cs.padding };
}

// Button
const btn = document.querySelector('button[type="submit"], [class*="continue"]');
if (btn) {
  const cs = getComputedStyle(btn);
  results.button = { bg: cs.backgroundColor, color: cs.color, borderRadius: cs.borderRadius, font: cs.fontFamily, fontSize: cs.fontSize, padding: cs.padding };
}

// Stats "18+"
const stats = document.querySelectorAll('[class*="stat"], [class*="number"], [class*="count"]');
stats.forEach((s, i) => {
  const cs = getComputedStyle(s);
  if (s.textContent.includes('18') || s.textContent.includes('14') || s.textContent.includes('100')) {
    results[`stat_${i}`] = { text: s.textContent.trim().substring(0, 20), font: cs.fontFamily, size: cs.fontSize, weight: cs.fontWeight };
  }
});

// Ticker bar
const ticker = document.querySelector('[class*="ticker"], [class*="marquee"], [class*="scroll"]');
if (ticker) {
  const cs = getComputedStyle(ticker);
  results.ticker = { bg: cs.backgroundColor, font: cs.fontFamily, fontSize: cs.fontSize, height: cs.height, padding: cs.padding };
}

// Input fields
const input = document.querySelector('input');
if (input) {
  const cs = getComputedStyle(input);
  results.input = { bg: cs.backgroundColor, border: cs.border, borderRadius: cs.borderRadius, color: cs.color, font: cs.fontFamily, fontSize: cs.fontSize };
}

JSON.stringify(results, null, 2);

// Get more detailed styles from the access code page
const r = {};

// The big heading
const h1 = document.querySelector('h1');
if (h1) {
  const cs = getComputedStyle(h1);
  r.h1 = { font: cs.fontFamily, size: cs.fontSize, weight: cs.fontWeight, lineHeight: cs.lineHeight, color: cs.color, letterSpacing: cs.letterSpacing };
}

// Find the card container more carefully
const allDivs = document.querySelectorAll('div');
let cardDiv = null;
allDivs.forEach(d => {
  const cs = getComputedStyle(d);
  if (d.textContent.includes('Enter your access code') && cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && !d.textContent.includes('Built for IB')) {
    if (!cardDiv || d.offsetWidth < cardDiv.offsetWidth) cardDiv = d;
  }
});
if (cardDiv) {
  const cs = getComputedStyle(cardDiv);
  r.card = { bg: cs.backgroundColor, borderRadius: cs.borderRadius, border: cs.border, padding: cs.padding, width: cs.width };
}

// All buttons
document.querySelectorAll('button').forEach((btn, i) => {
  const cs = getComputedStyle(btn);
  r[`btn_${i}_${btn.textContent.trim().substring(0,15)}`] = { bg: cs.backgroundColor, color: cs.color, borderRadius: cs.borderRadius, fontSize: cs.fontSize, fontWeight: cs.fontWeight, padding: cs.padding, border: cs.border, fontFamily: cs.fontFamily };
});

// Inputs 
document.querySelectorAll('input').forEach((inp, i) => {
  const cs = getComputedStyle(inp);
  r[`input_${i}`] = { bg: cs.backgroundColor, borderRadius: cs.borderRadius, border: cs.border, color: cs.color, fontSize: cs.fontSize, padding: cs.padding, fontFamily: cs.fontFamily };
});

// Labels
document.querySelectorAll('label, [class*="label"]').forEach((l, i) => {
  if (l.textContent.trim().length < 30) {
    const cs = getComputedStyle(l);
    r[`label_${i}_${l.textContent.trim()}`] = { fontSize: cs.fontSize, fontWeight: cs.fontWeight, letterSpacing: cs.letterSpacing, textTransform: cs.textTransform, color: cs.color };
  }
});

// Subtitle/paragraph text
document.querySelectorAll('p').forEach((p, i) => {
  const cs = getComputedStyle(p);
  const text = p.textContent.trim().substring(0, 40);
  if (text.length > 10) {
    r[`p_${i}_${text}`] = { fontSize: cs.fontSize, color: cs.color, fontFamily: cs.fontFamily, lineHeight: cs.lineHeight };
  }
});

JSON.stringify(r, null, 2);

const r = {};

// Score circle/number
const scoreEls = document.querySelectorAll('[class*="score"], [class*="circle"], [class*="ring"]');
scoreEls.forEach((el, i) => {
  const cs = getComputedStyle(el);
  const text = el.textContent?.trim().substring(0, 20);
  if (text) r[`score_${i}`] = { text, width: cs.width, height: cs.height, borderRadius: cs.borderRadius, bg: cs.background?.substring(0,100), border: cs.border, fontSize: cs.fontSize, fontWeight: cs.fontWeight, fontFamily: cs.fontFamily, color: cs.color };
});

// Progress bars
const bars = document.querySelectorAll('[class*="progress"], [role="progressbar"]');
bars.forEach((b, i) => {
  const cs = getComputedStyle(b);
  r[`bar_${i}`] = { width: cs.width, height: cs.height, borderRadius: cs.borderRadius, bg: cs.background?.substring(0,100) };
});

// Badges (Pass, Critical, Warning, Interview-Ready)
const badges = document.querySelectorAll('[class*="badge"], [class*="tag"], [class*="pill"], [class*="status"]');
badges.forEach((b, i) => {
  const cs = getComputedStyle(b);
  const text = b.textContent?.trim().substring(0, 20);
  if (text) r[`badge_${i}_${text}`] = { bg: cs.backgroundColor, color: cs.color, borderRadius: cs.borderRadius, fontSize: cs.fontSize, padding: cs.padding, fontWeight: cs.fontWeight, border: cs.border };
});

// Nav bar
const nav = document.querySelector('nav, header, [class*="nav"]');
if (nav) {
  const cs = getComputedStyle(nav);
  r.nav = { bg: cs.backgroundColor, height: cs.height, padding: cs.padding, borderBottom: cs.borderBottom };
}

// Section headers like "CRITICAL FIXES", "BANK FIT ANALYSIS"
document.querySelectorAll('h2, h3, h4').forEach((h, i) => {
  const cs = getComputedStyle(h);
  const text = h.textContent?.trim().substring(0, 40);
  if (text && text.length > 3) r[`section_${i}_${text}`] = { fontSize: cs.fontSize, fontWeight: cs.fontWeight, letterSpacing: cs.letterSpacing, textTransform: cs.textTransform, fontFamily: cs.fontFamily, color: cs.color };
});

// Issue/warning cards
const issueCards = document.querySelectorAll('[class*="issue"], [class*="warning"], [class*="fix"]');
issueCards.forEach((c, i) => {
  const cs = getComputedStyle(c);
  if (cs.borderLeft !== '0px none rgb(0, 0, 0)' || cs.backgroundColor !== 'rgba(0, 0, 0, 0)') {
    r[`issue_${i}`] = { bg: cs.backgroundColor, borderLeft: cs.borderLeft, borderRadius: cs.borderRadius, padding: cs.padding, border: cs.border };
  }
});

// Sidebar cards
const sideCards = document.querySelectorAll('[class*="sidebar"] > div, [class*="side"] > div');
sideCards.forEach((c, i) => {
  const cs = getComputedStyle(c);
  if (cs.backgroundColor !== 'rgba(0, 0, 0, 0)') {
    r[`sidebar_${i}`] = { bg: cs.backgroundColor, borderRadius: cs.borderRadius, padding: cs.padding, border: cs.border };
  }
});

// Export/Re-upload buttons  
document.querySelectorAll('button, a[class*="btn"]').forEach((b, i) => {
  const cs = getComputedStyle(b);
  const text = b.textContent?.trim().substring(0, 20);
  if (text && (text.includes('Export') || text.includes('Re-upload') || text.includes('Try'))) {
    r[`topbtn_${text}`] = { bg: cs.backgroundColor, color: cs.color, borderRadius: cs.borderRadius, border: cs.border, fontSize: cs.fontSize, padding: cs.padding };
  }
});

JSON.stringify(r, null, 2);

