</style></head><body>
<div class="tab-nav">
  <button class="tab-btn active" data-tab="tab-compare">Design Compare</button>
  <button class="tab-btn" data-tab="tab-landing">Landing</button>
  <button class="tab-btn" data-tab="tab-upload">Upload</button>
  <button class="tab-btn" data-tab="tab-results">Results</button>
</div>

<div id="tab-compare" class="tab-content active">
  <div class="dc-section" id="s1">
    <div class="dc-section-title">1 — Heading Font</div>
    <div class="dc-grid">
      <div class="dc-card selected" data-var="heading-font" data-val="'Georgia', serif" onclick="selectCard(this)">
        <div class="dc-label"><span>Georgia</span><span class="dc-tag dc-tag-cur">Current</span></div>
        <div class="dc-preview"><div style="font-family:Georgia;font-size:20px">Built for IB</div></div>
      </div>
      <div class="dc-card" data-var="heading-font" data-val="'Arial', sans-serif" onclick="selectCard(this)">
        <div class="dc-label"><span>Arial</span><span class="dc-tag dc-tag-alt">Alt</span></div>
        <div class="dc-preview"><div style="font-family:Arial;font-size:20px">Built for IB</div></div>
      </div>
      <div class="dc-card" data-var="heading-font" data-val="'Courier', monospace" onclick="selectCard(this)">
        <div class="dc-label"><span>Courier</span><span class="dc-tag dc-tag-alt">Alt</span></div>
        <div class="dc-preview"><div style="font-family:Courier;font-size:20px">Built for IB</div></div>
