      <div class="dc-card" data-var="bg-body" data-val="#1a1a2e" onclick="selectCard(this)">
        <div class="dc-label"><span>Navy</span><span class="dc-tag dc-tag-alt">Alt</span></div>
        <div class="dc-preview"><div style="width:100%;height:30px;background:#1a1a2e;border:1px solid #333;border-radius:4px"></div></div>
