      font-family: var(--mono-font);
      display: block;
      word-break: break-all;
    }

    /* PAGE CONTENT */
    .page-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 60px 40px;
    }

    .bank-ticker {
      overflow: hidden;
      padding: 12px 0;
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
      margin-bottom: 60px;
    }

    .bank-ticker-text {
      font-family: var(--body-font);
      font-size: 11px;
      font-weight: 500;
      color: var(--text-secondary);
      letter-spacing: 0.2em;
      white-space: nowrap;
    }

    .hero-section {
      display: flex;
      gap: 60px;
      align-items: flex-start;
    }

    .hero-left {
      flex: 1;
    }

    .hero-badge {
      font-size: 11px;
      color: var(--text-secondary);
      letter-spacing: 0.15em;
      margin-bottom: 20px;
    }

    .hero-title {
      font-family: var(--heading-font);
      font-size: 52px;
