<script>
var log=document.getElementById('test-log');
function tlog(msg){log.innerHTML+='<div>'+msg+'</div>';log.scrollTop=log.scrollHeight;}
tlog('Page loaded');

// Tab switching
document.querySelectorAll('.tab-btn').forEach(function(btn){
btn.addEventListener('click',function(){
document.querySelectorAll('.tab-btn').forEach(function(b){b.classList.remove('active')});
document.querySelectorAll('.tab-content').forEach(function(c){c.classList.remove('active')});
btn.classList.add('active');
var tabId=btn.getAttribute('data-tab');
var tabEl=document.getElementById(tabId);
if(tabEl){tabEl.classList.add('active');tlog('Tab: '+tabId+' OK');}
else{tlog('Tab: '+tabId+' MISSING!');}
});
});
tlog('Tabs: '+document.querySelectorAll('.tab-btn').length+' btns, '+document.querySelectorAll('.tab-content').length+' panes');

// Card selection
function selectCard(card){
var section=card.closest('.dc-section');
if(section){section.querySelectorAll('.dc-card').forEach(function(c){c.classList.remove('selected')});}
card.classList.add('selected');
var varName=card.getAttribute('data-var');
var varValue=card.getAttribute('data-val');
if(varName&&varValue&&varName!=='visual-only'){updateRootVar('--'+varName,varValue);tlog('Card: --'+varName+'='+varValue);}
else{tlog('Card: visual-only selected');}
}
tlog('Cards: '+document.querySelectorAll('.dc-card').length);

function updateRootVar(name,value){document.documentElement.style.setProperty(name,value);tlog('CSS var: '+name+'='+value);}

function toggleCtrlPanel(){
var p=document.getElementById('ctrlPanel');
p.classList.toggle('collapsed');
tlog('Ctrl panel toggled');
}

function resetTheme(){
['--heading-font','--body-font','--bg-body','--bg-card','--accent-gold','--text-primary','--text-secondary','--border-radius'].forEach(function(v){document.documentElement.style.removeProperty(v);});
tlog('Theme reset');
}

// Dragging
var panel=document.getElementById('ctrlPanel');
var header=document.getElementById('ctrlHeader');
if(panel&&header){
var isDragging=false,startX,startY,startLeft,startTop;
header.addEventListener('mousedown',function(e){
if(e.target.tagName==='BUTTON')return;
isDragging=true;
startX=e.clientX;startY=e.clientY;
var rect=panel.getBoundingClientRect();
startLeft=rect.left;startTop=rect.top;
panel.style.transition='none';
});
document.addEventListener('mousemove',function(e){
if(!isDragging)return;
panel.style.right='auto';panel.style.bottom='auto';
panel.style.left=(startLeft+e.clientX-startX)+'px';
panel.style.top=(startTop+e.clientY-startY)+'px';
});
document.addEventListener('mouseup',function(){isDragging=false;panel.style.transition='';});
tlog('Drag: ready');
}else{tlog('ERROR: ctrl panel not found!');}

tlog('=== ALL INIT DONE ===');
</script>
</body></html>`);
document.close();
