import base64, json

with open('/sessions/stoic-relaxed-carson/mnt/outputs/interactive-mockup.html', 'r') as f:
    html = f.read()

b64 = base64.b64encode(html.encode('utf-8')).decode('ascii')

# Split into chunks that fit in JS tool calls (~25KB each)
chunk_size = 25000
chunks = [b64[i:i+chunk_size] for i in range(0, len(b64), chunk_size)]

# Write each chunk as a ready-to-execute JS string
for i, chunk in enumerate(chunks):
    js = f'window._b64 += "{chunk}"; window._chunkCount++; "Chunk {i} added, total " + window._b64.length + " chars"'
    with open(f'/sessions/stoic-relaxed-carson/exec_chunk_{i}.js', 'w') as f:
        f.write(js)

# Write the assembly script
assembly = """
var b64 = window._b64;
var binary = atob(b64);
var bytes = new Uint8Array(binary.length);
for (var i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
var blob = new Blob([bytes], {type: 'text/html; charset=utf-8'});
var url = URL.createObjectURL(blob);
window.location.href = url;
'Navigating to blob URL, HTML size: ' + binary.length;
"""
with open('/sessions/stoic-relaxed-carson/exec_assemble.js', 'w') as f:
    f.write(assembly)

print(f"Created {len(chunks)} chunk files + assembly script")
for i, c in enumerate(chunks):
    print(f"  exec_chunk_{i}.js: JS string {len(c)} b64 chars")
PYEOF

