function toggleCtrlPanel(){document.getElementById('ctrlPanel').classList.toggle('collapsed');tlog('Toggle panel');}
function resetTheme(){
['--heading-font','--body-font','--bg-body','--bg-card','--accent-gold','--text-primary','--text-secondary','--color-green','--color-red','--color-orange','--border-radius'].forEach(function(v){document.documentElement.style.removeProperty(v);});
tlog('Reset');
}
function saveTheme(){
var m={generatedAt:new Date().toISOString(),cssVariables:{},selections:{}};
var s=document.documentElement.style;
for(var i=0;i<s.length;i++){var p=s[i];if(p.startsWith('--'))m.cssVariables[p]=s.getPropertyValue(p).trim();}
document.querySelectorAll('.dc-card.selected').forEach(function(c){
var sec=c.closest('.dc-section');
var title=sec?(sec.querySelector('.dc-section-title')||{textContent:'?'}).textContent:'?';
m.selections[title]=c.querySelector('div:first-child').textContent;
});
var blob=new Blob([JSON.stringify(m,null,2)],{type:'application/json'});
var url=URL.createObjectURL(blob);
var a=document.createElement('a');a.href=url;a.download='design-manifest.json';a.click();
URL.revokeObjectURL(url);
tlog('Manifest downloaded!');
}

tlog('Color pickers: '+document.querySelectorAll('input[type=color]').length);
tlog('Save btn: '+(document.querySelector('[onclick*=saveTheme]')?'YES':'NO'));
tlog('Ready');
</script></body></html>`);
