    .category-progress-fill { height:100%; border-radius:3px; }
    .category-score { font-family:var(--mono-font); font-size:11px; color:var(--text-secondary); min-width:40px; text-align:right; }
    .issue-card { background:var(--bg-card); border:2px solid var(--color-red); border-left-width:6px; border-radius:var(--border-radius); padding:20px; margin-bottom:16px; }
    .issue-badge { display:inline-block; background:var(--color-red); color:white; padding:4px 8px; border-radius:3px; font-size:10px; font-weight:600; margin-bottom:8px; }
    .issue-title { font-size:14px; font-weight:600; color:var(--text-primary); margin-bottom:8px; }
    .issue-description { font-size:12px; color:var(--text-secondary); margin-bottom:16px; line-height:1.6; }
    .issue-before-after { display:grid; grid-template-columns:1fr 1fr; gap:12px; padding-top:16px; border-top:1px solid rgba(255,255,255,0.06); }
    .before-text { background:rgba(231,76,60,0.1); padding:8px; border-left:2px solid var(--color-red); border-radius:3px; color:var(--text-secondary); font-size:11px; line-height:1.5; }
    .after-text { background:rgba(46,204,113,0.1); padding:8px; border-left:2px solid var(--color-green); border-radius:3px; color:var(--text-primary); font-size:11px; line-height:1.5; }
    .sidebar-card { background:var(--bg-card); border:1px solid rgba(255,255,255,0.08); border-radius:var(--border-radius); padding:16px; margin-bottom:16px; }
    .sidebar-card-title { font-size:11px; font-weight:600; color:var(--text-secondary); letter-spacing:0.05em; margin-bottom:12px; text-transform:uppercase; }
    .sidebar-item { display:flex; justify-content:space-between; padding:8px 0; border-bottom:1px solid rgba(255,255,255,0.06); font-size:12px; }
    .sidebar-item:last-child { border-bottom:none; }

    /* CTRL PANEL */
    .ctrl-panel { position:fixed; bottom:20px; right:20px; width:320px; background:var(--bg-card); border:1px solid rgba(255,255,255,0.1); border-radius:var(--border-radius); box-shadow:0 8px 32px rgba(0,0,0,0.5); z-index:999; overflow:hidden; }
