    .ctrl-header button { background:transparent; border:none; color:var(--text-secondary); cursor:pointer; font-size:18px; line-height:1; padding:0; width:24px; height:24px; display:flex; align-items:center; justify-content:center; }
    .ctrl-header button:hover { color:var(--text-primary); }
    .ctrl-body { padding:16px; max-height:60vh; overflow-y:auto; }
    .ctrl-group { margin-bottom:16px; }
    .ctrl-group label { display:block; font-size:10px; font-weight:600; color:var(--text-secondary); letter-spacing:0.05em; margin-bottom:6px; text-transform:uppercase; }
    .ctrl-group select { width:100%; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); color:var(--text-primary); padding:8px 10px; border-radius:var(--input-radius); font-family:var(--body-font); font-size:12px; cursor:pointer; }
