html = r'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8">
<title>IB Resume BA — Design System Test</title>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;500;600;700&family=Cormorant+Garamond:wght@400;500;600&family=Libre+Baskerville:wght@400;700&family=Inter:wght@300;400;500;600;700&family=DM+Sans:wght@300;400;500;600;700&family=Space+Grotesk:wght@400;500;600&family=DM+Mono:wght@400;500&family=JetBrains+Mono:wght@400;500&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">
<style>
:root{--heading-font:'Playfair Display',serif;--body-font:'Inter',sans-serif;--mono-font:'DM Mono',monospace;--accent-font:'Inter',sans-serif;--accent-gold:#C9A96E;--bg-body:#0A0A0A;--bg-card:#141312;--text-primary:#F5F5F5;--text-secondary:#888;--color-green:#2ECC71;--color-red:#E74C3C;--color-orange:#F39C12;--border-radius:6px;--btn-radius:6px;--input-radius:6px}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--bg-body);color:var(--text-primary);font-family:var(--body-font);line-height:1.6}
.tab-nav{position:sticky;top:0;z-index:100;display:flex;gap:1px;background:rgba(10,10,10,0.97);padding:0 8px;border-bottom:1px solid rgba(255,255,255,0.08)}
.tab-btn{padding:12px 18px;background:transparent;border:none;border-bottom:2px solid transparent;color:var(--text-secondary);font-family:'Inter',sans-serif;cursor:pointer;font-size:11px;font-weight:600;letter-spacing:0.05em;white-space:nowrap;transition:all 0.2s}
.tab-btn:hover{color:var(--text-primary)}
.tab-btn.active{color:var(--text-primary);border-bottom-color:var(--accent-gold)}
.tab-content{display:none;animation:fadeIn 0.3s}.tab-content.active{display:block}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.dc-split{display:grid;grid-template-columns:1fr 380px;gap:30px;max-width:1500px;margin:0 auto;padding:30px}
.dc-right{position:sticky;top:70px;height:max-content;max-height:calc(100vh - 90px);overflow-y:auto;background:var(--bg-card);border:1px solid rgba(255,255,255,0.08);border-radius:var(--border-radius);padding:16px}
.dc-section{margin-bottom:40px}
.dc-section-title{font-family:var(--heading-font);font-size:18px;font-weight:500;margin-bottom:12px;padding-bottom:10px;border-bottom:1px solid rgba(255,255,255,0.06)}
.dc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
.dc-card{background:var(--bg-card);border:1px solid rgba(255,255,255,0.08);border-radius:var(--border-radius);padding:12px;cursor:pointer;transition:all 0.2s;position:relative}
.dc-card:hover{border-color:rgba(255,255,255,0.15)}
.dc-card.selected{border-color:var(--accent-gold);background:rgba(201,169,110,0.08)}
