btn.classList.add('active');
document.getElementById(btn.getAttribute('data-tab')).classList.add('active');
});
});

// Update CSS variable
function updateRootVar(name,value){
document.documentElement.style.setProperty(name,value);
}

// Card selection with Current tag movement
function selectCard(card){
var section=card.closest('.dc-section');
if(section){
section.querySelectorAll('.dc-card').forEach(function(c){
c.classList.remove('selected');
var tag=c.querySelector('.dc-tag');
if(tag){tag.classList.remove('dc-tag-cur');tag.classList.add('dc-tag-alt');tag.textContent='Alt';}
});
}
card.classList.add('selected');
var cardTag=card.querySelector('.dc-tag');
if(cardTag){cardTag.classList.remove('dc-tag-alt');cardTag.classList.add('dc-tag-cur');cardTag.textContent='Current';}
var varName=card.getAttribute('data-var');
var varValue=card.getAttribute('data-val');
if(varName&&varValue&&varName!=='visual-only'){
updateRootVar('--'+varName,varValue);
var ctrl=document.getElementById('ctrl-'+varName);
if(ctrl){
for(var i=0;i<ctrl.options.length;i++){
if(ctrl.options[i].value===varValue){ctrl.selectedIndex=i;break;}
}
}
}
}

// Sync cards from control panel
function syncCardsFromCtrl(varName,value){
var cards=document.querySelectorAll('.dc-card[data-var="'+varName+'"]');
var found=false;
cards.forEach(function(c){
c.classList.remove('selected');
var tag=c.querySelector('.dc-tag');
if(tag){tag.classList.remove('dc-tag-cur');tag.classList.add('dc-tag-alt');tag.textContent='Alt';}
if(c.getAttribute('data-val')===value&&!found){
c.classList.add('selected');
var t=c.querySelector('.dc-tag');
if(t){t.classList.remove('dc-tag-alt');t.classList.add('dc-tag-cur');t.textContent='Current';}
found=true;
}
});
}

// Reset
var defaults={'--heading-font':"'Playfair Display', serif",'--body-font':"'Inter', sans-serif",'--mono-font':"'DM Mono', monospace",'--accent-font':"'Inter', sans-serif",'--accent-gold':'#C9A96E','--bg-body':'#0A0A0A','--bg-card':'#141312','--text-primary':'#F5F5F5','--text-secondary':'#888888','--color-green':'#2ECC71','--color-red':'#E74C3C','--color-orange':'#F39C12','--border-radius':'6px','--btn-radius':'6px','--input-radius':'6px'};
function resetDefaults(){
for(var k in defaults){updateRootVar(k,defaults[k]);}
document.querySelectorAll('.dc-card').forEach(function(c,i){
var section=c.closest('.dc-section');
if(!section)return;
var isFirst=c===section.querySelector('.dc-card');
c.classList.toggle('selected',isFirst);
var tag=c.querySelector('.dc-tag');
if(tag){
if(isFirst){tag.classList.remove('dc-tag-alt');tag.classList.add('dc-tag-cur');tag.textContent='Current';}
else{tag.classList.remove('dc-tag-cur');tag.classList.add('dc-tag-alt');tag.textContent='Alt';}
}
});
var hf=document.getElementById('ctrl-heading-font');if(hf)hf.selectedIndex=0;
var bf=document.getElementById('ctrl-body-font');if(bf)bf.selectedIndex=0;
}

// Save theme
function saveTheme(){
var theme={};
var style=getComputedStyle(document.documentElement);
for(var k in defaults){theme[k]=style.getPropertyValue(k).trim()||defaults[k];}
theme.selections={};
document.querySelectorAll('.dc-card.selected').forEach(function(c){
var v=c.getAttribute('data-var');
var section=c.closest('.dc-section');
var title=section?section.querySelector('.dc-section-title').textContent:'';
var label=c.querySelector('.dc-label span:first-child');
theme.selections[title]={variable:v,value:c.getAttribute('data-val'),label:label?label.textContent:''};
});
var blob=new Blob([JSON.stringify(theme,null,2)],{type:'application/json'});
var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='design-manifest.json';a.click();
}

// Drag panel
var panel=document.getElementById('ctrlPanel');
var header=document.getElementById('ctrlHeader');
var dragging=false,dx=0,dy=0;
header.addEventListener('mousedown',function(e){
if(e.target.tagName==='BUTTON')return;
dragging=true;dx=e.clientX-panel.offsetLeft;dy=e.clientY-panel.offsetTop;
});
document.addEventListener('mousemove',function(e){
if(!dragging)return;
panel.style.left=(e.clientX-dx)+'px';panel.style.top=(e.clientY-dy)+'px';
panel.style.right='auto';panel.style.bottom='auto';
});
document.addEventListener('mouseup',function(){dragging=false;});
</script>
</body></html>'''

