file.content:
// 2. CARD SELECTION (moves yellow border + Current tag)
function selectCard(card) {
  var section = card.closest('.dc-section');
  if (section) {
    section.querySelectorAll('.dc-card').forEach(function(c) {
      c.classList.remove('selected');
      var tag = c.querySelector('.dc-tag');
      if (tag) { tag.classList.remove('dc-tag-cur'); tag.classList.add('dc-tag-alt'); tag.textContent = 'Alt'; }
    });
  }
  card.classList.add('selected');
  var cardTag = card.querySelector('.dc-tag');
  if (cardTag) { cardTag.classList.remove('dc-tag-alt'); cardTag.classList.add('dc-tag-cur'); cardTag.textContent = 'Current'; }
  var varName = card.getAttribute('data-var');
  var varValue = card.getAttribute('data-val');
  if (varName && varValue && varName !== 'visual-only') {
    updateRootVar('--' + varName, varValue);
    var ctrl = document.getElementById('ctrl-' + varName);
    if (ctrl) { for (var i = 0; i < ctrl.options.length; i++) { if (ctrl.options[i].value === varValue) { ctrl.value = varValue; break; } } }
  }
}

// 3. UPDATE CSS VARIABLE
function updateRootVar(name, value) {
  document.documentElement.style.setProperty(name, value);
}

// 4. RESET THEME
function resetTheme() {
  var defaults = {
    '--heading-font': "'Playfair Display', serif", '--body-font': "'Inter', sans-serif",
    '--mono-font': "'DM Mono', monospace", '--accent-font': "'Inter', sans-serif",
    '--accent-gold': '#C9A96E', '--bg-body': '#0A0A0A', '--bg-card': '#141312',
    '--text-primary': '#F5F5F5', '--text-secondary': '#888888',
    '--color-green': '#2ECC71', '--color-red': '#E74C3C', '--color-orange': '#F39C12',
    '--border-radius': '6px', '--btn-radius': '6px', '--input-radius': '6px'
  };
  for (var k in defaults) document.documentElement.style.setProperty(k, defaults[k]);
  document.querySelectorAll('.dc-section').forEach(function(s) {
    s.querySelectorAll('.dc-card').forEach(function(c, i) {
      var tag = c.querySelector('.dc-tag');
      if (i === 0) { c.classList.add('selected'); if (tag) { tag.classList.remove('dc-tag-alt'); tag.classList.add('dc-tag-cur'); tag.textContent = 'Current'; } }
      else { c.classList.remove('selected'); if (tag) { tag.classList.remove('dc-tag-cur'); tag.classList.add('dc-tag-alt'); tag.textContent = 'Alt'; } }
    });
  });
  document.querySelectorAll('.ctrl-group select').forEach(function(sel) { sel.selectedIndex = 0; });
}

