// 3b. SYNC CARDS FROM CONTROL PANEL DROPDOWN
function syncCardsFromCtrl(varName, value) {
  var cards = document.querySelectorAll('.dc-card[data-var="' + varName + '"]');
  var found = false;
  cards.forEach(function(c) {
    c.classList.remove('selected');
    var tag = c.querySelector('.dc-tag');
    if (tag) { tag.classList.remove('dc-tag-cur'); tag.classList.add('dc-tag-alt'); tag.textContent = 'Alt'; }
    if (c.getAttribute('data-val') === value && !found) {
      c.classList.add('selected');
      var t = c.querySelector('.dc-tag');
      if (t) { t.classList.remove('dc-tag-alt'); t.classList.add('dc-tag-cur'); t.textContent = 'Current'; }
      found = true;
    }
  });
}

