.ctrl-panel { position:fixed; bottom:20px; right:20px; width:320px; background:var(--bg-card); border:1px solid rgba(255,255,255,0.1); border-radius:var(--border-radius); box-shadow:0 8px 32px rgba(0,0,0,0.5); z-index:999; overflow:hidden; }
.ctrl-panel.collapsed .ctrl-body { display:none; }
.ctrl-header { display:flex; justify-content:space-between; align-items:center; padding:14px 16px; background:rgba(201,169,110,0.1); border-bottom:1px solid rgba(255,255,255,0.08); cursor:move; }
.ctrl-header h3 { font-family:var(--heading-font); font-size:14px; font-weight:500; color:var(--text-primary); margin:0; }
.ctrl-header button { background:transparent; border:none; color:var(--text-secondary); cursor:pointer; font-size:18px; line-height:1; padding:0; width:24px; height:24px; display:flex; align-items:center; justify-content:center; }
.ctrl-header button:hover { color:var(--text-primary); }
.ctrl-body { padding:16px; max-height:60vh; overflow-y:auto; }
.ctrl-group { margin-bottom:16px; }
.ctrl-group label { display:block; font-size:10px; font-weight:600; color:var(--text-secondary); letter-spacing:0.05em; margin-bottom:6px; text-transform:uppercase; }
.ctrl-group select { width:100%; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); color:var(--text-primary); padding:8px 10px; border-radius:var(--input-radius); font-family:var(--body-font); font-size:12px; cursor:pointer; }
.ctrl-divider { border:none; height:1px; background:rgba(255,255,255,0.06); margin:16px 0; }
.btn-reset { width:100%; background:rgba(201,169,110,0.2); color:var(--accent-gold); border:1px solid var(--accent-gold); padding:10px; border-radius:var(--btn-radius); font-weight:600; font-size:11px; cursor:pointer; transition:all 0.2s ease; }
.btn-reset:hover { background:rgba(201,169,110,0.3); }

